INSERT INTO leyes (id,titulo,siglas,tipo,fecha_publicacion,fecha_ultima_reforma,vigente,url_original,temas_clave) VALUES ('8d4ad440-ecec-5f73-8aff-e8d9d4246a24','Acuerdo de la Comisión Nacional de Energía por el que se inicia el procedimiento administrativo de caducidad a los titulares de ciento treinta y dos permisos de comercialización de hidrocarburos, petrolíferos y petroquímicos, por presuntamente ubicarse en la hipótesis de caducidad prevista en el artículo 88, fracción I, inciso b, de la Ley del Sector Hidrocarburos.','CNE-INICIO-CADUCIDAD-132-2026','acuerdo','2026-10-27',NULL,NULL,'https://dof.gob.mx/nota_detalle.php?codigo=5802184&fecha=27/10/2026',ARRAY['Hidrocarburos','Comercialización','Inicio de procedimiento de caducidad','CNE']);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('09b08def-cc2c-5c33-b17b-5999d0cc050e','8d4ad440-ecec-5f73-8aff-e8d9d4246a24','Preámbulo','<h1> ACUERDO de la Comisión Nacional de Energía por el que se inicia el procedimiento administrativo de caducidad a los titulares de ciento treinta y dos permisos de comercialización de hidrocarburos, petrolíferos y petroquímicos, por presuntamente ubicarse en la hipótesis de caducidad prevista en el artículo 88, fracción I, inciso b, de la Ley del Sector Hidrocarburos.</h1>
<h2> Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Comisión Nacional  de Energía.</h2>
<div> JUAN CARLOS SOLÍS ÁVILA, Director General de la Comisión Nacional de Energía, con fundamento en los artículos 14, 16, 28, noveno párrafo y 90, primer párrafo, de la Constitución Política de los Estados Unidos Mexicanos; 1, 2, fracción I, 17, 26, fracción IX, y 33, último párrafo de la Ley Orgánica de la Administración Pública Federal; 1, primer párrafo, 2, 3, 4, 13, 35, y 36 de la Ley Federal de Procedimiento Administrativo; 1, 3, fracciones III, IV y V, 5, 76, fracción II, 77, 87, fracción III, 88 y 116, fracción I y transitorio Décimo Tercero de la Ley del Sector Hidrocarburos; 1, 2, primer párrafo, 3, 5, 6, 7, fracciones I, II, III, V, XX y XXII, 9, fracciones II, III, IV y VI, 16, fracciones I, X, XIX, XXII y XXV, 17, fracciones I, II, III, IV, y XIV, y transitorios Tercero, Séptimo, Octavo, y Noveno de la Ley de la Comisión Nacional de Energía; 2, 6, 330 y transitorios Segundo, Tercero y Vigésimo del Reglamento de la Ley del Sector Hidrocarburos; 2, apartado F, fracción III, 71, 77 y 78 del Reglamento Interior de la Secretaría de Energía, 9 y 12, fracción XI del Reglamento Interior de la Comisión Nacional de Energía, 7, fracción II del Acuerdo CT/1.SE/2-2025, Aprobación de las Reglas de Operación del Comité Técnico de la Comisión Nacional de Energía, así como en el Acuerdo número CT/19.SO/35-2026 emitido por el Comité Técnico de la Comisión Nacional de Energía, y</div>
<div> CONSIDERANDO<br/> </div>','1','preambulo','Acuerdo','Identificación y fundamentos',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('12534142-bc6f-54cb-8c9b-05e13c709f86','8d4ad440-ecec-5f73-8aff-e8d9d4246a24','Considerandos','<div> Que conforme al párrafo segundo del artículo 14 de la Constitución Política de los Estados Unidos Mexicanos, nadie puede ser privado de la libertad o de sus propiedades, posesiones o derechos, sino mediante juicio seguido ante las autoridades previamente establecidas, en el que se debe de cumplir con las formalidades esenciales del procedimiento y conforme a las Leyes expedidas con anterioridad al hecho.</div>
<div> Que el artículo 16 de la Constitución Política de los Estados Unidos Mexicanos, establece que nadie puede ser molestado en su persona, familia, domicilio, papeles o posesiones, sino en virtud de mandamiento escrito de la autoridad competente, que funde y motive la causa legal del procedimiento.</div>
<div> Que el artículo 28, párrafo noveno, de la Constitución Política de los Estados Unidos Mexicanos establece que el Poder Ejecutivo Federal, por conducto de la dependencia encargada de conducir y supervisar la política energética del país, cuenta con atribuciones para llevar a cabo la regulación técnica y económica; así como la facultad sancionadora en materia energética y de hidrocarburos.</div>
<div> Que conforme al artículo 4 de la Ley Federal de Procedimiento Administrativo, los actos administrativos de carácter general, tales como reglamentos, decretos, acuerdos, normas oficiales mexicanas, circulares y formatos, así como los lineamientos, criterios, metodologías, instructivos, directivas, reglas, manuales, así como disposiciones que tengan por objeto establecer obligaciones específicas cuando no existan condiciones de competencia y cualesquiera de naturaleza análoga a los actos anteriores, que expidan las dependencias y organismos descentralizados de la Administración Pública Federal, deben publicarse en el Diario Oficial de la Federación para que produzcan efectos jurídicos.</div>
<div> Que, el 18 de marzo de 2025, en cumplimiento al decreto de reforma constitucional en materia de simplificación orgánica, publicado en el Diario Oficial de la Federación el 20 de diciembre de 2024, fue publicado en el mismo medio de difusión, el decreto por el que se reforman, adicionan y derogan diversas disposiciones y se expiden, entre otras leyes, la Ley de la Comisión Nacional de Energía y la Ley del Sector Hidrocarburos, a partir de la cual se extingue a la Comisión Reguladora de Energía y se crea la Comisión Nacional de Energía.</div>
<div> Que, de conformidad con los artículos 2, primer párrafo de la Ley de la Comisión Nacional de Energía; y 2 del Reglamento Interior de la Comisión Nacional de Energía, la Comisión Nacional de Energía es un órgano administrativo desconcentrado de carácter técnico, sectorizado a la Secretaría de Energía, que cuenta con independencia técnica, operativa, de gestión y de decisión en los términos de dicha Ley, misma que tiene por objeto regular, supervisar e imponer sanciones a las actividades del sector energético, de acuerdo a sus competencias, a fin de promover el desarrollo ordenado, continuo y seguro de las actividades del sector energético.</div>
<div> Que de conformidad con el artículo 7, fracciones I y III, de la Ley de la Comisión Nacional de Energía, la Comisión Nacional de Energía, en el ámbito de sus atribuciones, tiene la facultad de emitir actos y resoluciones con carácter técnico, administrativo y operativo sobre las actividades en materia energética, vigilar y supervisar su cumplimiento, así como para emitir las resoluciones, acuerdos y demás actos administrativos necesarios para el cumplimiento de sus atribuciones.</div>
<div> Que de conformidad con el artículo 7, fracción V, de la Ley de la Comisión Nacional de Energía, la Comisión Nacional de Energía tiene facultades para otorgar, modificar, actualizar, revocar y extinguir los títulos de permisos, autorizaciones y demás actos administrativos sobre las actividades en materia energética.</div>
<div> Que de acuerdo con lo establecido en el artículo 7, fracciones VI y IX, de la Ley de la Comisión Nacional de Energía, la Comisión Nacional de Energía tiene la facultad de solicitar a los sujetos regulados la información y la documentación necesaria que requiera para el ejercicio de sus atribuciones. Asimismo, en el ámbito de sus atribuciones, tiene la facultad de ordenar y realizar visitas de verificación, inspección o supervisión, y requerir la presentación de información y documentación.</div>
<div> Que el artículo 7, fracción XX, de la Ley de la Comisión Nacional de Energía establece que la Comisión Nacional de Energía tiene la facultad de iniciar, tramitar y resolver los procedimientos administrativos que con motivo de sus atribuciones se promuevan, en atención a las disposiciones aplicables.</div>
<div> Que, de acuerdo con el artículo 9, fracciones II, III y IV, de la Ley de la Comisión Nacional de Energía, la Comisión Nacional de Energía cuenta con las atribuciones para otorgar, modificar, terminar y supervisar los títulos de permisos para el procesamiento, licuefacción, regasificación, compresión, descompresión, transporte, almacenamiento, distribución, comercialización y expendio al público de gas natural; los títulos de permisos de formulación, transporte, almacenamiento, distribución, comercialización y expendio al público de petrolíferos y los títulos de permisos de transporte, almacenamiento y comercialización de petroquímicos.</div>
<div> Que, el artículo Tercero transitorio de la Ley de la Comisión Nacional de Energía establece que las referencias normativas a la extinta Comisión Reguladora de Energía se entienden hechas o conferidas a la Secretaría de Energía o a la Comisión Nacional de Energía, conforme a las atribuciones, competencias y facultades que les correspondan.</div>
<div> Que, el artículo Séptimo transitorio de la Ley de la Comisión Nacional de Energía establece que todas las disposiciones, normas, lineamientos, políticas, criterios y demás normatividad emitida por la extinta Comisión Reguladora de Energía continúan en vigor en lo que no se opongan a dicha Ley, sin perjuicio de que sean adecuadas, modificadas o sustituidas, en términos de la normatividad aplicable.</div>
<div> Que, de conformidad con el artículo Octavo transitorio, párrafo cuarto, de la Ley de la Comisión Nacional de Energía, los permisos y demás actos emitidos por la extinta Comisión Reguladora de Energía, continúan surtiendo efectos hasta el término de su vigencia de conformidad con la normatividad bajo la cual hayan sido formalizados. No obstante, la Comisión Nacional de Energía puede realizar la vigilancia y supervisión de su cumplimiento y, en su caso, ser objeto de terminación anticipada o revocación.</div>
<div> Que, de conformidad con el artículo Décimo transitorio de la Ley de la Comisión Nacional de Energía, estableció que a la entrada en vigor de dicha Ley, la extinta Comisión Reguladora de Energía, en términos de la normatividad aplicable, realizó las acciones correspondientes para llevar a cabo una transferencia ágil y eficiente de toda la información, expedientes, sistemas y cualquier documentación que detentara, a efectos de dar continuidad a la atención de los asuntos que así lo requirieran por parte de la Secretaría de Energía y la Comisión Nacional de Energía respectivamente.</div>
<div> Que, de conformidad con el considerando anterior, la Comisión Nacional de Energía, recibió la transferencia de la totalidad de información, expedientes, sistemas y la documentación que detentó la extinta Comisión Reguladora de Energía, incluidos los expedientes asociados a los permisos de comercialización materia del presente Acuerdo, a efectos de dar continuidad a dichos asuntos. Asimismo, la Comisión Nacional de Energía, asumió sus respectivas atribuciones, competencias y facultades sobre las actividades en materia energética.</div>
<div> Que la Ley del Sector Hidrocarburos, en su artículo 76, fracción II, establece que para la realización de las actividades de procesamiento, licuefacción, regasificación, compresión, descompresión, transporte, almacenamiento, distribución, comercialización y expendio al público de gas natural; formulación, transporte, almacenamiento, distribución, comercialización, expendio al público y despacho para autoconsumo de petrolíferos; transporte, almacenamiento y comercialización de petroquímicos, así como la gestión de sistemas integrados, requieren de un título de permiso otorgado por la Comisión Nacional de Energía.</div>
<div> Que el artículo 76, párrafo segundo, de la Ley del Sector Hidrocarburos, establece que las personas permisionarias de las actividades a que se refiere dicho artículo, deben cumplir con las obligaciones de entrega semanal de información relacionada con los controles volumétricos, medición y calidad de los hidrocarburos, petrolíferos y petroquímicos objeto de los permisos respectivos, así como de las operaciones comerciales que realicen con clientes y proveedores, y cualquier otra información que las autoridades competentes requieran para fines de supervisión y estadísticos del sector energético, en los términos y condiciones que establezcan el Reglamento de la Ley del Sector Hidrocarburos y demás normatividad aplicable.</div>
<div> Que el artículo 77 de la Ley del Sector Hidrocarburos, establece que en ejercicio de sus facultades de supervisión la Comisión Nacional de Energía para verificar el cumplimiento de las obligaciones inherentes a los permisos, no son aplicables los secretos comercial, bancario, fiscal ni fiduciario, sin perjuicio del tratamiento que las autoridades competentes deban tener respecto de dicha información en términos de la legislación aplicable.</div>
<div> Que el artículo 87, fracción III, de la Ley del Sector Hidrocarburos, establece que los títulos de permisos pueden terminar por caducidad, además, dispone que la terminación del título de permiso no exime a la persona permisionaria de las responsabilidades contraídas durante la vigencia del permiso.</div>
<div> Que el artículo 88 fracción I, de la Ley del Sector Hidrocarburos establece que, el título de permiso caduca cuando las personas permisionarias no ejercen los derechos conferidos en el título del permiso dentro del plazo establecido para tal efecto o, a falta de plazo, que las personas permisionarias no ejercen los derechos conferidos en el título del permiso durante un periodo consecutivo de trescientos sesenta y cinco días naturales.</div>
<div> Que el artículo 119 fracción VI de la Ley del Sector Hidrocarburos, establece que las personas permisionarias de las actividades reguladas por la Comisión Nacional de Energía deben, entre otras obligaciones, prestar los servicios de forma eficiente, uniforme, homogénea, regular, segura y continua, así como cumplir los términos y condiciones contenidos en los permisos.</div>
<div> Que el 3 de octubre de 2025, se publicó en el Diario Oficial de la Federación, el Reglamento de la Ley del Sector Hidrocarburos; en el cual establece en su artículo 2 que la Comisión Nacional de Energía, en el ámbito de sus competencias, se encuentra facultada para emitir o, en su caso, actualizar los actos administrativos de carácter general, tales como acuerdos, normas, normas oficiales mexicanas, estándares, circulares, formatos, permisos, aprobaciones y autorizaciones, así como los lineamientos, criterios, metodologías, guías, directivas, reglas, manuales, disposiciones que tengan por objeto establecer obligaciones generales o específicas y cualesquiera de naturaleza análoga a los actos anteriores, respecto de las actividades reguladas en la Ley del Sector Hidrocarburos, sin perjuicio de las facultades que, en su caso, correspondan a otras dependencias y entidades de la Administración Pública Federal.</div>
<div> Que en términos del artículo 330 del Reglamento de la Ley del Sector Hidrocarburos, se establece que la declaración de caducidad de los títulos de permisos debe realizarse por la Comisión Nacional de Energía, en el ámbito de su respectiva competencia, previa garantía de audiencia que se otorgue a las personas reguladas.</div>
<div> Que, atendiendo a la naturaleza y condiciones de la actividad de comercialización, la supervisión del ejercicio de los derechos conferidos mediante los títulos de permisos, resulta necesaria para verificar el desarrollo de las actividades permisionadas y el cumplimiento de las obligaciones respectivas, mediante requerimientos de información y mecanismos de control previstos en la Ley del Sector Hidrocarburos, y en su caso, a partir de la identificación de indicios respecto de la falta de la actividad o ejercicio de los derechos durante el plazo previsto en el artículo 88, fracción I, inciso b, de la Ley del Sector Hidrocarburos, resulta procedente el inicio del procedimiento administrativo de caducidad correspondiente.</div>
<div> Que, el artículo 32, fracción XV del Reglamento Interior de la Comisión Nacional de Energía, la Unidad de Hidrocarburos tiene como parte de sus atribuciones supervisar y vigilar el cumplimiento de la regulación, normas oficiales mexicanas y a las disposiciones administrativas de carácter general aplicables, a quienes realicen o supervisen las actividades reguladas.</div>
<div> Que, para efectos de la revisión referida en el Considerando anterior, y conforme a lo previsto en el Acuerdo A/014/2018, publicado en el Diario Oficial de la Federación el 9 de abril de 2018, por el que la extinta Comisión Reguladora de Energía actualizó los formatos para el cumplimiento de obligaciones referentes a las actividades de almacenamiento, distribución, comercialización y expendio de petrolíferos, en consistencia con la política pública de almacenamiento mínimo de petrolíferos emitida por la Secretaría de Energía, las personas permisionarias de comercialización de petrolíferos se encuentran obligadas a presentar los reportes de información previstos en dicho acuerdo.</div>
<div> Que, la Comisión Nacional de Energía en ejercicio de las atribuciones de supervisión y verificación de los permisos otorgados para realizar actividades del sector hidrocarburos, por conducto de la Unidad de Hidrocarburos conforme a lo dispuesto en el artículo 32, fracciones XV y XXXVI, del Reglamento Interior de la Comisión Nacional de Energía, llevó a cabo, el 1 de septiembre de 2026, la revisión de los expedientes electrónicos y físicos a su cargo, en la que se identificaron indicios en ciento treinta y dos expedientes asociados a títulos de permisos de comercialización, en los cuales las personas titulares no registraban actividades de compraventa de hidrocarburos, petrolíferos y petroquímicos durante el periodo consecutivo de trescientos sesenta y cinco días naturales, comprendido del 1 de septiembre de 2025 al 31 de agosto de 2026, sin que obrara constancia, aviso o registro alguno, que acreditara la realización de la actividad conferida en los respectivos títulos de permisos.</div>
<div> Que las formalidades esenciales del procedimiento constituyen elementos necesarios para garantizar una adecuada y oportuna defensa por la persona permisionaria previo a la emisión de un acto de autoridad, entre las que se encuentran la notificación del inicio del procedimiento y sus consecuencias, la oportunidad de ofrecer y desahogar pruebas, la posibilidad de formular las manifestaciones y alegatos, así como la emisión de una resolución que dirima las cuestiones debatidas en el procedimiento administrativo correspondiente, en términos de las tesis de rubros "FORMALIDADES ESENCIALES DEL PROCEDIMIENTO. SON LAS QUE GARANTIZAN UNA ADECUADA Y OPORTUNA DEFENSA PREVIA AL ACTO PRIVATIVO." (P./J. 47/95, registro digital 200234) y "AUDIENCIA, GARANTIA DE. DEBE RESPETARSE, AUNQUE LA LEY EN QUE SE FUNDE LA RESOLUCION IMPUGNADA NO PREVEA EL PROCEDIMIENTO PARA TAL EFECTO." (registro digital 245168).</div>
<div> Que, de acuerdo con los criterios contenidos en diversas resoluciones emitidas por la Suprema Corte de Justicia de la Nación, en donde refiere que la caducidad de una autorización, concesión o asignación constituye un mecanismo de control y redistribución de la autorización para llevar a cabo una actividad o ejercer un derecho, que no busca inhibir una conducta o castigarla, sino que es una consecuencia por la inactividad, omisión o el desinterés de ejercer un derecho. Asimismo, establece que la caducidad se traduce en una consecuencia que extingue un derecho ante su no ejercicio y, como tal, debe acatarse el principio de seguridad jurídica previsto en el artículo 16 constitucional.</div>
<div> Que, de acuerdo con las consideraciones expuestas, resulta necesario iniciar, tramitar y sustanciar, respecto de cada uno de los títulos de permiso correspondientes, un procedimiento administrativo de caducidad en términos de los artículos 87, fracción III, y 88, fracción I, inciso b, de la Ley del Sector Hidrocarburos, así como 330 del Reglamento de la Ley del Sector Hidrocarburos, a efecto de garantizar el derecho de audiencia de las personas permisionarias.</div>
<div> Que, en la Décimo Novena Sesión Ordinaria, celebrada el 13 de octubre de 2026, el Comité Técnico de la Comisión Nacional de Energía aprobó el Acuerdo CT/19.SO/35-2026, mediante el cual se aprueba el presente Acuerdo.</div>
<div> Que en el ejercicio de las facultades conferidas por la normatividad aplicable y, en apego a los objetivos y principios señalados en las consideraciones anteriores, y con la finalidad de dar a conocer la aprobación del Acuerdo CT/19.SO/35-2026, se expide el siguiente:</div>','2','preambulo','Acuerdo','Identificación y fundamentos',NULL);
INSERT INTO articulos (id,ley_id,identificador,contenido,orden,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre) VALUES ('fbe869f2-0cc9-5734-9e86-7f7595329ecf','8d4ad440-ecec-5f73-8aff-e8d9d4246a24','PRIMERO','<div> ACUERDO DE LA COMISIÓN NACIONAL DE ENERGÍA POR EL QUE SE INICIA EL PROCEDIMIENTO<br/> ADMINISTRATIVO DE CADUCIDAD A LOS TITULARES DE CIENTO TREINTA Y DOS PERMISOS DE<br/> COMERCIALIZACIÓN DE HIDROCARBUROS, PETROLÍFEROS Y PETROQUÍMICOS, POR PRESUNTAMENTE<br/> UBICARSE EN LA HIPÓTESIS DE CADUCIDAD PREVISTA EN EL ARTÍCULO 88, FRACCIÓN I, INCISO B, DE LA LEY<br/> DEL SECTOR HIDROCARBUROS<br/> </div>
<div> PRIMERO. Con fundamento en el acuerdo CT/19.SO/35-2026 aprobado por el Comité Técnico de la Comisión Nacional de Energía, en su sesión del 13 de octubre de 2026 y en los artículos 17, fracción IV, de la Ley de la Comisión Nacional de Energía y 19 del Reglamento Interior de la Comisión Nacional de Energía, se informa que se inicia el procedimiento administrativo de caducidad a las ciento treinta y dos personas titulares de los permisos de Comercialización de Gas Natural, Gas Licuado de Petróleo, Petrolíferos distintos a Gas Licuado de Petróleo y Petroquímicos que se relacionan a continuación, a efecto de otorgar la garantía de audiencia previa para determinar si se actualiza la hipótesis prevista en el artículo 88, fracción I, inciso b, de la Ley del Sector Hidrocarburos, en relación con el artículo 87, fracción III, del mismo ordenamiento y el artículo 330 del Reglamento de la Ley del Sector Hidrocarburos.</div>
